const csccStandardOfCare: NonNullable<CancerInput["standardOfCare"]> = [
  { setting: "Radiotherapy after surgery, and what not to add to it", approach: "For high-risk disease, surgery followed by postoperative radiotherapy of 60 to 66 Gy. The habit of adding chemotherapy, carried over from head and neck oncology, was tested in TROG 05.01: 321 patients randomised to postoperative radiotherapy with or without weekly carboplatin, with freedom from locoregional relapse at five years of 87 against 83 per cent, hazard ratio 0.84 (0.46 to 1.55, p=0.58), and no difference in disease-free or overall survival. Carboplatin should not be added. The control arm is the number to carry forward: surgery and radiotherapy alone controlled 83 per cent of these tumours locoregionally at five years, and only 7 per cent failed first at a distant site.", refs: ["trog-05-01", "radiotherapy-for-skin-cancer", "carboplatin", "perineural-invasion"], guideline: { version: "TROG 05.01 (Journal of Clinical Oncology 2018)", url: SRC.trog0501 } },

  { setting: "Before surgery, when the operation would be disfiguring", approach: "Up to four doses of cemiplimab before an operation planned with curative intent. In 79 patients with resectable stage II to IV disease, a pathological complete response, meaning no viable tumour cells anywhere in the specimen on central review, was found in 40 (51 per cent, 39 to 62) and a pathological major response in a further 10 (13 per cent). Imaging understated it, at 68 per cent objective response. Grade 3 or higher adverse events occurred in 18 per cent. What the trial does not answer is whether the surgery can then be reduced or omitted, because everyone was resected; that is the next question and it is the same one being asked in rectal and bladder cancer.", refs: ["neoadjuvant-cemiplimab-cscc", "cemiplimab", "pcr", "surgical-margins-keratinocyte-cancer"], guideline: { nccn: "Category 2A", version: "NCCN Guidelines: Squamous Cell Skin Cancer", url: SRC.nccnScc } },

  { setting: "The transplant recipient and the immunosuppressed patient", approach: "A group with 65 to 100 times the ordinary risk, tumours that are multiple and far more likely to spread, and almost no evidence, because every registration trial excluded them. Three levers. Switching immunosuppression: TUMORAPA randomised 120 kidney transplant recipients who had already had one of these cancers and found new squamous cell carcinomas in 22 per cent after a switch to sirolimus against 39 per cent continuing a calcineurin inhibitor (relative risk 0.56, 0.32 to 0.98), at the price of 60 serious adverse events against 14 and 23 per cent stopping the drug. Chemoprevention: acitretin and nicotinamide, with the nicotinamide effect not reproduced in transplant recipients. Immunotherapy, long refused because of the risk to the graft: a twelve-patient phase 1 study that cross-tapered to a mammalian target of rapamycin inhibitor and pulsed prednisone around each cycle reported no rejection and no graft loss, with responses in 5 of 11 evaluable patients. That is the whole prospective evidence base.", refs: ["skin-cancer-after-organ-transplant", "tumorapa", "cemiplimab-kidney-transplant-cscc", "acitretin", "nicotinamide", "cemiplimab"], guideline: { version: "TUMORAPA (New England Journal of Medicine 2012) and the Dana-Farber phase 1 (Journal of Clinical Oncology 2024)", url: SRC.cemiplimabKtr } },

  { setting: "What is available in England", approach: "NICE technology appraisal TA802 recommendation 1.1 recommends cemiplimab for metastatic or locally advanced cutaneous squamous cell carcinoma in adults when curative surgery or curative radiotherapy is not suitable, only if it is stopped at 24 months or earlier on progression and the company supplies it under the commercial arrangement. It replaced TA592, which had recommended it within the Cancer Drugs Fund. That single appraisal is the extent of NICE guidance for this disease: pembrolizumab and cosibelimab have not been appraised for it, and the adjuvant indication that C-POST supports has no appraisal either.", refs: ["cemiplimab", "pembrolizumab", "cosibelimab", "c-post"], guideline: { version: "NICE TA802 recommendation 1.1 (cemiplimab recommended, stopped at 24 months)", url: SRC.ta802 } },
];

